import {
    Directive,
    ElementRef,
    Input,
    OnChanges,
    OnDestroy,
    SimpleChanges,
    AfterViewInit,
} from '@angular/core';
import { Chart, ChartType, registerables } from 'chart.js';
import { TranslateService } from 'app/utils/translate/translate.service';
import { fromEvent, debounceTime } from 'rxjs';

@Directive({
    selector: 'canvas[baseDoughnut]',
})
export class DoughnutDirective implements OnDestroy, OnChanges, AfterViewInit {
    @Input() data: number[] = [];
    @Input() percents: string[] = [];
    chart: any;
    spam: string = '';
    ham: string = '';

    private chartInitialized = false;
    private pendingUpdate = false;

    private langChangeSubscription = this.translate.translate.onLangChange.subscribe(() => {
        this.update();
    });

    // native ChartJS resizing doesn't work well in DirectAdmin Evolution skin
    private resizeSubscription = fromEvent(window, 'resize').pipe(
        debounceTime(400),
    ).subscribe(() => {
        if (this.chart) {
            this.adjustCanvasSize();
            this.chart.resize();
        }
    });

    constructor(
        public element: ElementRef,
        public translate: TranslateService,
    ) {
        this.updateTranslation();
        Chart.register(...registerables);
    }

    ngAfterViewInit(): void {
        setTimeout(() => {
            if (this.data && this.data.length > 0 && !this.chartInitialized) {
                this.initializeChart();
            }
        }, 0);
    }

    private adjustCanvasSize(): void {
        const MIN_HEIGHT = 265;
        const RATIO = 1.6666666;
        const canvas = this.element.nativeElement;
        const parent = canvas.parentElement;
        if (parent && parent.offsetWidth > 0) {
            canvas.width = parent.offsetWidth;
            let computedHeight = Math.floor(canvas.width / RATIO);
            if (!Number.isFinite(computedHeight) || computedHeight <= 0) {
                computedHeight = canvas.height || MIN_HEIGHT;
            }
            canvas.height = Math.max(MIN_HEIGHT, computedHeight);
        }
    }

    private initializeChart(): void {
        if (this.chartInitialized || this.chart) {
            return;
        }

        this.adjustCanvasSize();

        let context = this.element.nativeElement.getContext('2d');
        let options = {
            type: 'doughnut' as ChartType,
            data: this.getData(),
            options: {
                aspectRatio: 1.6666666,
                maintainAspectRatio: false,
                elements: {
                    arc: {
                      borderWidth: 0.5,
                    }
                },
                cutout: '65%',
                plugins: {
                    legend: {
                        labels: {
                            usePointStyle: true,
                            fontColor: '#000',
                        },
                    },
                    tooltips: {
                        callbacks: {
                            label: (tooltipItems, data) => {
                                return this.getLabels()[tooltipItems.index];
                            }
                        }
                    },
                    tooltip: {
                        usePointStyle: true,
                        callbacks: {
                            labelPointStyle: function(context) {
                                return {
                                    pointStyle: 'circle' as 'circle',
                                    rotation: 0,
                                };
                            }
                        },
                        boxPadding: 3,
                        caretSize: 0,
                        cornerRadius: 3,
                    },
                },
            },
            plugins: [{
                id: 'legendMargin',
                beforeInit: (chart, legend, options) => {
                    const originalFit = chart.legend.fit;
                    chart.legend.fit = function fit() {
                        // to use `this` correctly inside it
                        originalFit.bind(chart.legend)();
                        return this.height += 25;
                    }
                }
            }],
        };

        this.chart = new Chart(context, options);
        this.chartInitialized = true;

        if (this.pendingUpdate) {
            this.pendingUpdate = false;
            this.update();
        }

        setTimeout(() => {
            if (this.chart) {
                this.adjustCanvasSize();
                this.chart.resize();
            }
        }, 100);
    }

    ngOnChanges(changes: SimpleChanges): void {
        if (!this.data) return;

        this.data = changes.data?.currentValue || this.data;

        if (!this.chartInitialized && this.data.length > 0) {
            this.pendingUpdate = true;
            setTimeout(() => {
                if (!this.chartInitialized && this.data.length > 0) {
                    this.initializeChart();
                }
            }, 100);
            return;
        }

        if (this.chartInitialized) {
            this.update();
        }
    }

    async update() {
        await this.updateTranslation();
        if (!this.chart) return;
        this.chart.data = this.getData();
        this.chart.update();
    }

    ngOnDestroy(): any {
        if (this.chart) {
            this.chart.destroy();
            this.chart = void 0;
        }

        this.langChangeSubscription.unsubscribe();
        this.resizeSubscription.unsubscribe();
        this.chartInitialized = false;
    }

    getData(): any {
        return {
            labels: this.getLabels(),
            datasets: [{
                backgroundColor: ["#4EB675", "#D95140"],
                data: this.data,
            }],
        };
    }

    getLabels() {
        return [
            `${this.ham}: ${this.data[0]} (${this.percents[0]}%)`,
            `${this.spam}: ${this.data[1]} (${this.percents[1]}%)`,
        ]
    }

    private async updateTranslation() {
        this.spam = await this.translate.t('dashboard.incidentsAndAlerts.spam_ham.spam');
        this.ham = await this.translate.t('dashboard.incidentsAndAlerts.spam_ham.ham');
    }
}
